func (w *FsnotifyWatcher) Start() error {
	fw, err := fsnotify.NewWatcher()
	if err != nil {
		return err
	}
	if err := fw.Add(w.path); err != nil {
		fw.Close()
		return err
	}
	w.fw = fw
	w.done = make(chan struct{})
	go w.loop()
	return nil
}

